// Traducao de jogo.elf::main (pseudo-C do Craft Anything). O arquivo vem do manifesto, ja carregado em bytes.
// Original: le 64 bytes; < 12 bytes -> -2; magic != "QZX1" -> -2; senao u16 em 8 * u16 em 10 (little-endian, x86-64).
export function main(dados) {
  if (!dados) return -1; // fopen falhou
  if (dados.length <= 11) return -2;
  if (dados[0] !== 0x51 || dados[1] !== 0x5a || dados[2] !== 0x58 || dados[3] !== 0x31) return -2;
  const v = new DataView(dados.buffer, dados.byteOffset, dados.byteLength);
  return v.getUint16(8, true) * v.getUint16(10, true);
}
